import AppKit

/// Google's official "Sign in with Google" pill (iOS assets, 2x), unchanged as the branding rules ask.
/// Embedded because a SwiftPM resource bundle is not found once the app runs from another Mac.
enum GoogleButtonArt {
    static let light = image("")
    static let dark = image("")

    /// Points are half the pixels: the art is drawn at 2x.
    private static func image(_ base64: String) -> NSImage {
        let image = Data(base64Encoded: base64).flatMap(NSImage.init(data:)) ?? NSImage()
        image.size = NSSize(width: image.size.width / 2, height: image.size.height / 2)
        return image
    }
}
